-- Onion OS name badge (self-contained: embeds + displays its own image)
-- Controls: CANCEL = back to Onion OS, SELECT = redraw

local b64 = ""
local image_name = "badge.pbm"

-- base64 decode -> raw PBM bytes
local function b64decode(data)
  local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local lookup = {}
  for i = 1, #chars do lookup[chars:sub(i, i)] = i - 1 end
  data = data:gsub("[^" .. chars .. "]", "")
  local out = {}
  local i = 1
  while i <= #data do
    local c1 = lookup[data:sub(i, i)] or 0
    local c2 = lookup[data:sub(i + 1, i + 1)] or 0
    local c3 = lookup[data:sub(i + 2, i + 2)]
    local c4 = lookup[data:sub(i + 3, i + 3)]
    out[#out + 1] = string.char(((c1 << 2) | (c2 >> 4)) & 0xFF)
    if c3 then out[#out + 1] = string.char(((c2 << 4) | (c3 >> 2)) & 0xFF) end
    if c4 then out[#out + 1] = string.char(((c3 << 2) | (c4 >> 6)) & 0xFF) end
    i = i + 4
  end
  return table.concat(out)
end

-- Write the image into SPIFFS where onion.display_bitmap can read it.
-- display_bitmap("name") reads SPIFFS "/images_name"; via Lua io that path
-- lives under the VFS mount, so try the common candidates.
local function ensure_image()
  -- already present?
  for _, n in ipairs(onion.images()) do
    if n == image_name then return true end
  end
  local bytes = b64decode(b64)
  local candidates = {
    "/spiffs/images_" .. image_name,
    "/images_" .. image_name,
  }
  for _, path in ipairs(candidates) do
    local f = io.open(path, "wb")
    if f then
      f:write(bytes)
      f:close()
      -- confirm the firmware can see it
      for _, n in ipairs(onion.images()) do
        if n == image_name then return true end
      end
    end
  end
  return false
end

local function show()
  local ok, err = onion.display_bitmap(image_name, -1, -1, true)
  if not ok then onion.log(err or "display failed") end
  return ok
end

if not ensure_image() then
  onion.log("Could not stage badge image")
  onion.release_display()
  return
end

show()

-- wait for release of any held button, then loop
local last = onion.buttons()
while true do
  local btn = onion.buttons()
  if btn.cancel and not last.cancel then
    onion.release_display()
    return
  elseif btn.select and not last.select then
    show()
  end
  last = btn
  onion.sleep(80)
end
